import{_ as o,o as a,c as i,a2 as t}from"./chunks/framework.BN2sqjC1.js";const u=JSON.parse('{"title":"ADR-0047 — Apertura dei file per tipo e presentazioni Marp (.marp)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0047-apertura-file-per-tipo-e-presentazioni-marp.md","filePath":"adr/0047-apertura-file-per-tipo-e-presentazioni-marp.md"}'),n={name:"adr/0047-apertura-file-per-tipo-e-presentazioni-marp.md"};function r(d,e,c,l,s,p){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0047-—-apertura-dei-file-per-tipo-e-presentazioni-marp-marp" tabindex="-1">ADR-0047 — Apertura dei file per tipo e presentazioni Marp (<code>.marp</code>) <a class="header-anchor" href="#adr-0047-—-apertura-dei-file-per-tipo-e-presentazioni-marp-marp" aria-label="Permalink to &quot;ADR-0047 — Apertura dei file per tipo e presentazioni Marp (`.marp`)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata; parzialmente superata da <a href="./0048-presentazioni-marp-slideshow-ribbon-pptx.html">ADR-0048</a> (vista divisa e PPTX)</td></tr><tr><td><strong>Data</strong></td><td>2026-11-03</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.2.1 (matrice funzioni), §2.3 (editor e rendering), §3.4.5 (strategia per tipo di file), §3.4.6 (scope di sync); V-02/D-01, D-04, V-07; ADR-0020, ADR-0027, ADR-0029, ADR-0030, ADR-0045</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì (§3.4.5: <code>.marp</code> entra nella riga «Markdown»; §3.4.6: <code>.marp</code> nel contenuto sincronizzato; §2.2.1: nuove righe «Apertura file per tipo» e «Presentazioni Marp»; supera in parte ADR-0027, alternativa «file di slide dedicati») → richiede aggiornamento di <code>Specifications.md</code> da parte dell&#39;owner</td></tr><tr><td><strong>Superfici</strong></td><td>desktop (binding, host Wails, comandi) · workbench web (core WASM, download, comandi) · cloud: nessuna modifica (il server non interpreta il contenuto né il tipo) · console: nessuna</td></tr></tbody></table><blockquote><p><strong>Nota (M22, 2026-11-20).</strong> <a href="./0063-nomi-file-senza-estensione.html">ADR-0063</a>, <strong>accettata</strong> il 2026-11-20 (recepita in <code>Specifications.md</code> v1.8, 2026-11-20; <a href="./../spec-v1.8-proposta.html"><code>../spec-v1.8-proposta.md</code></a> resta come storia), usa il predicato di questo ADR («si apre in una scheda», <code>openTarget(path) === &#39;in-app&#39;</code>) per nascondere l&#39;estensione dei file supportati in tutta l&#39;interfaccia e per far conservare l&#39;estensione alla rinomina. La tabella di apertura qui sotto non cambia.</p></blockquote><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Il file explorer mostra già ogni file del vault: l&#39;unico filtro è sulle dot-cartelle (<code>.memobrain</code>, <code>.trash</code>, <code>.git</code>), che restano nascoste perché stato interno. Ma un file di tipo sconosciuto (<code>.zip</code>, <code>.docx</code>, <code>.pptx</code>, …) apre una tab con il solo segnaposto «embed-other»: non c&#39;è modo di aprirlo con l&#39;applicazione del sistema operativo, né di scaricarlo dal workbench web.</p><p>In parallelo si vogliono presentazioni <a href="https://marp.app/" target="_blank" rel="noreferrer">Marp</a> (Markdown con direttive, temi e rendering a slide 16:9), create e modificate nell&#39;app con editor e anteprima affiancati ed esportabili. ADR-0027 ha già introdotto le slide di una nota <code>.md</code> (pipeline reading, chiavi <code>slide-*</code>) e aveva scartato i file di slide dedicati per compatibilità Obsidian e merge a 3 vie. Marp è però un formato diverso (direttive, temi, <code>paginate</code>, sfondi <code>![bg]</code>) che la pipeline reading non riproduce; tenerlo in un&#39;estensione propria evita che le note <code>.md</code> cambino aspetto a seconda del frontmatter e separa nettamente le due funzioni.</p><p>Vincoli: nessun CSS personalizzato e HTML sanificato (V-02/D-01), funzionamento offline, CSP con <code>frame-src &#39;none&#39;</code> e senza <code>unsafe-eval</code> (desktop e web), finestra singola (V-07), parità desktop/web per costruzione (ADR-0045), budget dei bundle (ADR-0020).</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><h3 id="_1-apertura-dei-file-per-tipo" tabindex="-1">1. Apertura dei file per tipo <a class="header-anchor" href="#_1-apertura-dei-file-per-tipo" aria-label="Permalink to &quot;1. Apertura dei file per tipo&quot;">​</a></h3><p>Un unico gestore (<code>openFile</code> in <code>packages/workbench/src/app/openFile.ts</code>) decide in base all&#39;estensione, ed è agganciato a <code>openNote</code> dello store, così ogni punto d&#39;ingresso (explorer, quick switcher, ricerca, link) lo attraversa:</p><table tabindex="0"><thead><tr><th>Tipo</th><th>Desktop</th><th>Workbench web</th></tr></thead><tbody><tr><td>Note <code>.md</code>, <code>.canvas</code>, <code>.base</code>, <code>.excalidraw</code>, <code>.marp</code></td><td>Vista interna</td><td>Vista interna</td></tr><tr><td>Immagini (<code>png jpg jpeg gif svg webp bmp avif</code>), <code>pdf</code>, audio e video</td><td>Viewer interno esistente</td><td>Viewer interno esistente</td></tr><tr><td>Qualsiasi altro tipo, anche senza estensione</td><td>Applicazione predefinita del SO; nessuna tab</td><td>Dialog «Apertura File» — «Il file <code>&lt;nome&gt;</code> non può essere visualizzato direttamente. Desideri scaricarlo?» — <code>Annulla</code> / <code>Download</code></td></tr><tr><td>Eseguibili (<code>exe bat cmd com msi ps1 sh command app scr jar vbs lnk …</code>)</td><td>Mai aperti: avviso e «Mostra nella cartella»</td><td>Come gli altri tipi (download)</td></tr></tbody></table><ul><li>Nuova capability <code>openWithSystemApp</code> (desktop sì, browser no) e due metodi <code>Host</code> che essa governa: <code>OpenPath</code> e <code>RevealPath</code>, implementati sul desktop con i comandi del SO (<code>open</code>/<code>open -R</code>, <code>xdg-open</code>, <code>rundll32 url.dll,FileProtocolHandler</code>/<code>explorer /select,</code>).</li><li>Nuovi binding <code>VaultAPI.OpenWithSystemApp</code>, <code>VaultAPI.RevealInFolder</code> (path risolto con <code>FS.Resolve</code>, traversal rifiutato, eseguibili rifiutati anche lato Go) e <code>VaultAPI.DownloadFile</code> (<code>Host.SaveFile</code> + copia in streaming + <code>Host.Delivered</code>: nel browser è il download, sul desktop «Salva una copia…»; nessun limite di <code>ReadBinary</code>).</li><li>Le tab di tipo sconosciuto già salvate in <code>workspace.json</code> mostrano il segnaposto con il pulsante «Apri con l&#39;app predefinita» o «Scarica».</li></ul><h3 id="_2-il-file-marp" tabindex="-1">2. Il file <code>.marp</code> <a class="header-anchor" href="#_2-il-file-marp" aria-label="Permalink to &quot;2. Il file `.marp`&quot;">​</a></h3><ul><li>Estensione <code>.marp</code>, contenuto Markdown di Marp (frontmatter con <code>marp: true</code>). Il core Go lo classifica come markdown: <code>syncproto.KindOf(&quot;.marp&quot;) = KindMarkdown</code>. Ne seguono merge a 3 vie (anche tra utenti diversi, D-04), indice FTS, link e backlink, senza nuovi tipi nel protocollo.</li><li>Il server non cambia: il tipo è calcolato dal client. Un client di versione precedente classifica <code>.marp</code> come <code>other</code> e, in caso di conflitto, produce una <em>conflict copy</em>: nessuna perdita di dati.</li><li>Nessun nuovo parser condiviso: l&#39;indice usa il parser markdown esistente; il rendering a slide è solo nel frontend.</li></ul><h3 id="_3-rendering-marp-entro-v-02" tabindex="-1">3. Rendering Marp entro V-02 <a class="header-anchor" href="#_3-rendering-marp-entro-v-02" aria-label="Permalink to &quot;3. Rendering Marp entro V-02&quot;">​</a></h3><ul><li>Libreria <code>@marp-team/marp-core</code> a versione esatta, in un chunk lazy (come Canvas ed Excalidraw).</li><li>Solo i temi integrati (<code>default</code>, <code>gaia</code>, <code>uncover</code>): niente temi esterni né <code>@theme</code> personalizzati.</li><li>Disattivati tutti i canali di CSS dell&#39;autore: <code>html: false</code>, <code>inlineStyle: false</code>, chiave <code>style:</code> del frontmatter e commenti <code>&lt;!-- style: … --&gt;</code> rimossi prima del rendering. Le direttive del formato (<code>theme</code>, <code>paginate</code>, <code>header</code>, <code>footer</code>, <code>class</code>, <code>backgroundColor</code>, <code>color</code>, <code>backgroundImage</code>, <code>![bg]</code>) sono ammesse: generano stili da Marp, non CSS scritto dall&#39;utente.</li><li>Uscita sanificata: DOMPurify dedicato (ammette <code>svg</code>/<code>foreignObject</code>/<code>section</code> e l&#39;attributo <code>style</code> generato, scartando <code>url()</code> che non siano <code>data:</code> o <code>blob:</code>); CSS del tema privato di <code>@import</code> e <code>url()</code> remoti, sul modello di <code>sanitizeSvg</code> per Mermaid.</li><li>Isolamento in Shadow DOM (un iframe è escluso da <code>frame-src &#39;none&#39;</code>): il CSS del tema non tocca l&#39;interfaccia.</li><li>Offline: emoji come caratteri nativi (niente twemoji da CDN), matematica MathJax in SVG, font dei temi che usavano Google Fonts sostituiti dai font di sistema. Un test e2e verifica zero richieste di rete, come per Excalidraw.</li></ul><h3 id="_4-vista-creazione-e-presentazione" tabindex="-1">4. Vista, creazione e presentazione <a class="header-anchor" href="#_4-vista-creazione-e-presentazione" aria-label="Permalink to &quot;4. Vista, creazione e presentazione&quot;">​</a></h3><ul><li>Vista divisa: editor CodeMirror in modalità Source a sinistra, anteprima delle slide a destra aggiornata in tempo reale (debounce ~150 ms) e allineata alla slide del cursore.</li><li>Comando <code>marp:new</code> (template con <code>marp: true</code>, <code>theme: default</code>, <code>paginate: true</code> e due slide), presente anche nel menu dell&#39;explorer e nella ribbon. Presentazione a tutto schermo nella stessa finestra, come ADR-0027.</li><li>Funzione governata dal feature flag <code>presentations</code> del Config Profile.</li></ul><h3 id="_5-export" tabindex="-1">5. Export <a class="header-anchor" href="#_5-export" aria-label="Permalink to &quot;5. Export&quot;">​</a></h3><ul><li><strong>HTML</strong>: documento autonomo senza script (slide SVG impilate e responsive, immagini inline <code>data:</code>), che passa <code>checkStandaloneHTML</code>.</li><li><strong>PDF</strong>: stampa del documento con <code>@page { size: 1280px 720px; margin: 0 }</code> e una slide per pagina; si salva in PDF dal dialog di stampa, come l&#39;export delle note.</li><li><strong>PPTX</strong>: rinviato. Marp CLI lo produce con un Chromium headless, assente sia nella webview Wails sia nel browser; il comando <code>marp:export-pptx</code> è nel registro ma disabilitato, con l&#39;indicazione «Non ancora disponibile».</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong><code>.md</code> con <code>marp: true</code> nel frontmatter</strong> (convenzione di Marp, compatibile con Obsidian) — scartata per scelta di prodotto: una nota cambierebbe vista e aspetto a seconda di una chiave, e si sovrapporrebbe alle slide di ADR-0027. Resta un&#39;estensione possibile in futuro.</li><li><strong><code>.marp</code> come file opaco (<code>other</code>)</strong> — scartata: niente merge a 3 vie (solo copie di conflitto), niente ricerca né link.</li><li><strong>Anteprima in iframe con <code>srcdoc</code></strong> — scartata: <code>frame-src &#39;none&#39;</code> nella CSP di desktop e web.</li><li><strong>PPTX rasterizzato in JS (pptxgenjs, una immagine per slide)</strong> — rinviata: dipendenze pesanti e testo non modificabile; da rivalutare se richiesto.</li><li><strong>Mostrare anche le dot-cartelle nell&#39;explorer</strong> — scartata: espone <code>.memobrain/</code> (stato interno, in parte non sincronizzato) e <code>.git</code>.</li><li><strong>Aprire gli eseguibili come gli altri file</strong> — scartata: un click su un file arrivato con la sync di un vault condiviso eseguirebbe codice di altri.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Spec da aggiornare (owner): §3.4.5 riga «Markdown <code>.md</code>» → «Markdown <code>.md</code>, <code>.marp</code>»; §3.4.6 contenuto sincronizzato con <code>.marp</code>; §2.2.1 nuove righe; nota in ADR-0027 che i file <code>.marp</code> sono una funzione distinta dalle slide delle note.</li><li>Vault Obsidian: i <code>.marp</code> appaiono in Obsidian solo con l&#39;opzione «Detect all file extensions» e senza anteprima; gli altri strumenti Marp (VS Code, CLI) li leggono rinominandoli <code>.md</code>.</li><li>La parità è registrata in <code>shared/parity/features.yaml</code> con le voci <code>files.open-by-type</code> e <code>presentations.marp</code>.</li><li>Nuova dipendenza da tenere aggiornata e dentro i budget dei bundle; i temi di Marp sono la sola eccezione, limitata e sanificata, al divieto di CSS di terzi.</li><li>Debito accettato: export PPTX assente; da rivedere quando sarà disponibile un renderer senza Chromium o su richiesta esplicita.</li></ul>',24)])])}const g=o(n,[["render",r]]);export{u as __pageData,g as default};
